(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["\u0635109"] = {"atoms": {"ص109.1": {"x": [[1, "تجريد التوحيد المفيد\r\rللشيخ الإمام\rتقي الدين أحمد بن علي المقريزي\rالمتوفى عام 845 من الهجرة\r\rبسم الله الرحمن الرحيم\r\rالحمد لله رب العالمين ، والعاقبة للمتقين ، وصلى الله على نبينا محمد خاتم النبيين ، وعلى آله وصحبه أجمعين ..\r\rأما بعد ، فهذا كتاب جم الفوائد بديع الفرائد ، ينتفع به من أراد الله والدار الآخرة .. سميته (( تجريد التوحيد المفيد )) ، والله أسأل العون على العمل بمنه .\rاعلم أن الله سبحانه رب كل شيء ومالكه وإلههُ :\rفي معنى الرب :\rفالرب مصدر ربُّ يرَبُّ ربّاً فهو رابٌّ : فمعنى قوله تعالى } رَبِّ الْعَالَمِينَ { رابِّ العالمين ، فإن الرب سبحانه وتعالى هو الخالق الموجد لعباده ، القائم بتربيتهم وإصلاحهم من خَلقٍ ورزقٍ وعافية وإصلاح دين ودنيا .\rفي معنى الإلهية :\rوالإلهية كون العباد يتخذونه سبحانه محبوباً مألوهاً ويفردونه بالحب والخوف والرجاء والإخبات والتوبة والنذر والطاعة والطلب والتوكل ، ونحو هذه الأشياء . فإن التوحيد حقيقته أن ترى الأمور كلها من الله تعالى رؤية تقطع الالتفات إلى الأسباب والوسائط ، فلا ترى الخير والشر إلا منه تعالى ، وهذا المقام يثمر التوكل وترك شكاية الخلقِ وترك لومهم والرضا عن الله تعالى والتسليم لحكمه .\rوإذا عرفت ذلك فاعلم أن الربوبية منه تعالى لعباده والتَّأَلُّهَ من عباده له سبحانه ، كما أن الرحمة هي الوصلة بينهم وبينه عز وجل .\r\rبيان أن للتوحيد قشرين\r\rللتوحيد قشران :\rواعلم أن أنفس الأعمال وأجلها قدراً توحيد الله تعالى .. غير أن التوحيد له قشران : القشر الأول : أن تقول بلسانك لا إله إلا الله ، ويسمى هذا القول توحيداً ، وهو مناقض للتثليث الذي تعتقده النصارى ، وهذا التوحيد يصدر أيضاً من المنافق الذي يخالف سره جهره .\rالقشر الثاني :"], [2, "أن لايكون في القلب مخالفة ولا إنكار لمفهوم هذا القول ، بل يشتمل القلب على اعتقاده ذلك والتصديق به وهذا هو توحيد عامة الناس .\rلباب التوحيد وما يخرج عنه :\rولباب التوحيد أن يرى الأمور كلها لله تعالى ، ثم يقطع الالتفاف إلى الوسائط وأن يعبده سبحانه عبادة يفرده بها ولا يعبد غيره . ويخرج عن هذا التوحيد اتباع الهوى .. فكل من اتبع هواه فقد اتخذ هواه معبوده قال الله تعالى } أفرأيت من اتخذ إلهه هواه {\" الجاثية :23 \" .\rوإذا تأملت عرفت أن عابد الصنم لم يعبده ، وإنما عبد هواه ، وهو ميل نفسه إلى دين آبائه فيتبع ذلك الميل ، وميل النفس إلى المألوفات أحد المعاني التي يعبر عنها بالهوى ، ويخرج عن هذا التوحيد السخط على الخلق والالتفات إليهم ، فإن من يرى الكل من الله يسخط على غيره أو يأمل سواه . وهذا التوحيد مقام الصديقين .\rتوحيد الربوبية لابد معه من توحيد الإلهية :\rولا ريب أن توحيد الربوبية لم ينكره المشركون ، بل أقروا بأنه سبحانه وحده خالقهم وخالق السماوات والأرض ، والقائم بمصالح العالم كله ، وإنما أنكروا توحيد الإلهية والمحبة كما قد حكى الله تعالى عنهم في قوله } ومن الناس من يتخذ من دون الله أندادا يحبونهم كحب الله والذين آمنوا أشد حبا لله { \" البقرة :165\". فلما سووا غيره به في هذا التوحيد كانوا مشركين كما قال الله تعالى } الحمد لله الذي خلق السماوات والأرض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون{ \"الأنعام :1 \".\rوقد علّم الله سبحانه وتعالى عباده كيفية مباينة الشرك في توحيد الإلهية وأنه تعالى حقيق بإفراده وليّاً وحَكَماً وربّاً . فقال تعالى } قل أغير الله أتخذ ولياً{ \"الأنعام : 14 \" وقال } أفغير الله أبتغي حَكًماً {\"الأنعام : 114 \" وقال :} قل آغير الله أبغي رباً{\" الإنعام : 164\" .\r\rالفرق بين توحيد الربوبية وتوحيد الألوهية\r\rمن عدل بالله غيره فقد أشركَ :"], [3, "فلا وليَّ ولا حَكَمَ ولا رب إلا الله الذي من عَدَلَ به غيره فقد أشرك في ألوهيتهِ، ولو وحد ربوبيته ، فتوحيد الربوبية هو الذي اجتمعت فيه الخلائق ، مؤمنها وكافرها ، وتوحيد الألوهية مفرق الطرق بين المؤمنين والمشركين ، ولهذا كانت كلمة الإسلام لا إله إلا الله ، ولو قال لا رب إلا الله لما أجزأه عند المحققين ، فتوحيد الألوهية هو المطلوب من العباد . ولهذا كان أصل (( الله )) الإله ، كما هو قول سيبَوَيه ، وهو الصحيح وهو قول جمهور أصحابه ، إلا من شذ منهم .\rوبهذا الاعتبار الذي قررنا به الإله ، وأنه المحبوب لاجتماع صفات االكمال فيه كان الله هو الاسم الجامع لجميع معاني الأسماء الحسنى والصفات العليا ، وهو الذي ينكره المشركون ويحتج الرب سبحانه وتعالى عليهم بتوحيدهم ربوبيته على توحيد ألوهيته ، كما قال الله تعالى } قل الحمد لله وسلام على عباده الذين اصطفى ءآلله خير أما يشركون ، أمن خلق السماوات والأرض وأنزل لكم من السماء ماء فأنبتنا به حدائق ذات بهجة ماكان لكم أن تنبتوا شجرها أءله مع الله بل هم قوم يعدلون {\"النمل :59و60\". وكلما ذكر تعالى من آياته جملة من الجمل قال عقبها } أله مع الله {فأبان سبحانه وتعالى بذلك أن المشركين إنما كانوا يتوقفون في إثبات توحيد الإلهية لا الربوبية على أن منهم من أشرك في الربوبية كما يأتي بعد ذلك إن شاء الله تعالى .\rوبالجملة فهو تعالى يحتج على منكري الإلهية بإثباتهم الربوبية . ويتركهم سدىً معطلين لا يؤمرون ولا ينهون ، ولا يثابون ولا يعاقبون ، فإن الملك هو الآمر الناهي المعطى المانع الضار النافع المثيب المعاقب .\r\rالرب والملك والإله :"], [4, "ولذلك ، جاءت الاستعاذة في سورة الناس وسرة الفلق بالأسماء الحسنى الثلاثة ، الرب والملك والإله ، فإنه لما قال : } قل أعوذ رب الناس { كان فيه إثبات أنه خالقهم وفاطرهم ، فبقي أن يقال ، لما خلقهم هل كلفهم وأمرهم ونهاهم ؟ : قيل نعم ، فجاء }ملك الناس{ فأثبت الخلق والأمر . }أله له الخلق والأمر {\"الأعراف :54\" . فلما قيل ذلك ، قيل فإذا كان ربا موجداً وملكاَ مكلفاً ، فهل يُحَبُّ وَيُرَغَّبُ إليهِ،ويكون التوجه إليه غاية الخلق والأمر . قيل } إله الناس{ ، أي مألوهم ومحبوبهم الذي لا يتوجه العبد المخلوق المكلف العابد إلا له ، فجاءت الإلهية خاتمة وغاية وما قبلها كالتوطئة لها .\r\rأدلة الجمهور في سحر النبي - صلى الله عليه وسلم - وأدلة مخالفيه\r\rأعظمُ عَوذَةٍ في القرآن :\rوهاتان السورتان أعظم عَوذَةٍ في القرآن ، وجاءت الاستعاذة بهما في وقت الحاجة إلى ذلك ، وحين سُحر النبي - صلى الله عليه وسلم - وخُيّلَ إليه أنه يفعل الشيء - صلى الله عليه وسلم - وما فعله ، وأقام على ذلك أربعين يوما كما في الصحيح .\rوكانت عقدة السحر إحدى عشرة عقدة فأنزل الله المعوذتين إحدى عشرة آية ، فانحلت بكل آية عقدة وتعلقت الاستعاذة في أوائل القرآن باسمه الإله ، وهو المعبود وحده لاجتماع صفات الكمال فيه ومناجاة العبد لهذا الإله الكامل ذي الأسماء الحسنى والصفات العليا المرغوب إليه في أن يعيذ عبده الذي يناجيه بكلامه من الشيطان الحائل بينه وبين مناجاة ربه ، ثم استحب التعليق باسم الإله في جميع المواطن التي يقال فيها (( أعوذ بالله من الشيطان الرجيم )) لأن اسم الله تعالى هو الغاية للأسماء .\rولهذا كان كل اسم بعده لا يتعرف إلا به ، فتقول الله هو السلام المؤمن المهيمن ، فالجلالة تعرف غيرها ، وغيرها لا يعرفها ."], [5, "والذين أشركوا به تعالى في الربوبية منهم من أثبت معه خالقاً آخر وإن لم يقولوا إنه إله مكافئ له وهو المشركون ومن ضاهاهم من القدرية .\rوربوبيته سبحانه للعالم الربوبية الكاملة المطلقة الشاملة تبطل أقوالهم ، لأنها تقتضي ربوبيته لجميع ما فيه من الذوات والصفات والحركات والأفعال .\rوحقيقة قول القدرية المجوسية أنه تعالى ليس ربا لأفعال الحيوان ولا تتناولها ربوبيته إذ كيف يتناول ما لايدخل تحت قدرته ومشيئته وخلقه .\r\rبيان أن شرك الأمم كله نوعان\rبيان للشرك في العبادة :\rوشرك الأمم كله نوعان : شرك في الإلهية ، وشرك في الربوبية .. فالشرك في الإلهية والعبادة هو الغالب على أهل الإشراك ، وهو شرك عباد الأصنام وعباد الملائكة وعباد الجن وعباد المشايخ الصالحين الأحياء والأموات الذين قالوا }مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى{\"الزمر: من الآية3\" ويشفعوا لنا عنده ، وينالنا بسبب قربهم من الله وكرامته لهم قرب وكرامة ، كما هو المعهود في الدنيا من حصول الكرامة والزلفى لمن يخدم أعوان الملك وأقاربه وخاصته . والكتب الإلهية كلها من أولها إلى آخرها تبطل هذا المذهب وترده وتقبح أهله وتنص على أنهم أعداء الله تعالى ، وجميع الرسل صلوات الله عليهم متفقون على ذلك من أولهم إلى آخرهم ، وما أهلك الله تعالى من الأمم إلا بسبب هذا الشرك ومن أجله : وأصله الشرك في محبة الله تعالى ."], [6, "قال تعالى } يُحِبُّونَهُمْ كَحُبِّ اللَّهِ وَالَّذِينَ آمَنُوا أَشَدُّ حُبّاً لِلَّه{\"البقرة: من الآية165\" ، فأخبر سبحانه وتعالى أنه من أحب مع الله شيئا غيره كما يحبه ، فقد اتخذ ندِّا من دونه ، وهذا على أصح القولين في الآية أنهم يحبونهم كما يحبون الله ، وهذا هو العدل المذكور في قوله تعالى }ثُمَّ الَّذِينَ كَفَرُوا بِرَبِّهِمْ يَعْدِلُونَ{\"الأنعام: من الآية1\" ، والمعنى على أصح القولين أنهم يعدلون به غيره في العبادة فيسوون بينه وبين غيره في الحب والعبادة ، وكذلك قول المشركين في النار لأصنامهم }تَاللَّهِ إِنْ كُنَّا لَفِي ضَلالٍ مُبِينٍ،إِذْ نُسَوِّيكُمْ بِرَبِّ الْعَالَمِينَ{ \" الشعراء 97و98\" ومعلوم قطعا أن هذه التسوية لم تكن بينهم وبين الله في كونه ربهم وخالقهم ، فإنهم كانوا كما أخبر الله عنهم مقرين بأن الله تعالى وحده هو ربهم وخالقهم وأن الأرض ومن فيها لله وحده وأنه رب السماوات السبع ورب العرش العظيم ، وأنه سبحانه وتعالى هو الذي بيده ملكوت كل شيء وهو يجير ولا يجار عليه .\r\rالتسوية في المحبة والعبادة شرك لا يغفر :\rوإنما كانت هذه التسوية بينهم وبين الله تعالى في المحبة والعبادة فمن أحب غير الله تعالى وخافه ورجاه وذل له كما يحب الله تعالى ويخافه ويرجوه ، فهذا هو الشرك الذي لا يغفره الله ، فكيف بمن كان غير الله آثر عنده وأحب إليه وأخوف عنده ، وهو في مرضاته أشد سعياً منه في مرضاة الله ، فإذا كان المسوّى بين الله وبين غيرِه في ذلك مشركاً فما الظن بهذا . فعياذاً بالله من أن ينسلخ القلب من التوحيد والإسلام كانسلاخ الحية من قشرها وهو يظن أنه مسلم موحد فهذا أحد أنواع الشرك ."], [7, "والأدلة الدالة على أنه تعالى يجب أن يكون وحده هو المألوه يبطل هذا الشرك ويدحض حُجَج أهله ، وهي أكثر من أن يحيط بها إلا الله .. بل ما خلقه الله تعالى فهو آية شاهدة بتوحيده ، وكذلك كل ما أمر به ، فَخَلْقُهُ وأمره وما فطر عليه عباده وركبه فيهم من القوى شاهدٌ بأنه الله الذي لا إله إلا هو ، وأن كل معبود سواه باطل ، وأنه هو الحق المبين تقدس وتعالى .\rوواعجبا كيف يعصى الإله أم كيف يجحده الجاحد\rولله في كل تحريكه وتسكينه أبدا شاهد\rوفي كل شيء له آية تدل على أنه واحد\r\rالشرك في الربوبية أخبث شرك :\rوالنوع الثاني من الشرك ، الشرك به تعالى في الربوبية كشرك من جعل معه خالقا آخر كالمجوس وغيرهم الذين يقولون بأن للعالم ربَّين ، أحدهما خالق الخير ، ويقولون له بلسان الفارسية ((يزدان )) ، والآخر خالق الشر ويقول له المجوس بلسانهم (( أهرمن )) . وكالفلاسفة ومن تبعهم الذين يقولون بأنه لم يصدر عنه إلا واحد بسيط وأن مصدر المخلوقات كلها عن العقول والنفوس ، وأن مصدر هذا العالم عن العقل الفعال ، فهو رب كل ما تحته ومدبره ، وهذا أشر من عباد الأصنام والمجوس والنصارى وهو أخبث شرك في العالم ، إذ يتضمن من التعطيل وجحد الإلهية والربوبية واستناد الخلق إلى غيره سبحانه وتعالى مالم يتضمنه شرك أمة من الأمم . وشرك القدرية مختصر من هذا ، وباب يدخل منه إليه . ولهذا شبههم الصحابة رضي الله عنهم بالمجوس ، كما ثبت عن ابن عمر وابن عباس رضي الله عنهم ، وقد روى أهل السنن فيهم ذلك مرفوعا أنهم مجوس هذه الأمة ، وكثيرا ما يجتمع الشركان في العبد وينفرد أحدهما عن الآخر ، والقرآن الكريم ، بل الكتب المنزلة من عند الله تعالى كلها مصرحة بالرد على أهل الإشراك ، كقوله تعالى }إِيَّاكَ نَعْبُد { فإنه ينفي شرك المحبة والإلهية ، وقوله } وَإِيَّاكَ نَسْتَعِينُ{ فإنه ينفي شرك الخلق والربوبية ."], [8, "تفسير لتجريد التوحيد في الأفعال والألفاظ والإرادات :\rفتضمنت هذه الآية تجريد التوحيد لرب العالمين في العبادة وأنه لا يجوز إشراك غيره معه لا في الأفعال ولا في الألفاظ ولا في الإرادات ، فالشرك به في الأفعال كالسجود لغيره سبحانه وتعالى ، والطواف بغير بيته المحرم ، وحلق الرأس عبودية وخضوعاً لغيره ، وتقبيل الأحجار غير الحجر الأسود الذي هو يمينه تعالى في الأرض وتقبيل القبور واستلامها والسجود لها .\r\rالنهي عن اتخاذ القبور مساجد\rوقد لعن النبي صلى الله عليه وآله وسلم من اتخذ قبور الأنبياء والصالحين مساجد يصلى فيها .. فكيف من اتخذ القبور أوثانا تعبد من دون الله تعالى ، فهذا لم يعلم معنى قول الله تعالى }إِيَّاكَ نَعْبُد { وفي الصحيح عنه - صلى الله عليه وسلم - أنه قال (( لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد يُحَذِّر ما صنعوا )) وفيه عنه أيضا (( إن من شرار الناس من تدركهم الساعة وهم أحياء والذين يتخذون القبور مساجد )) ، وفيه أيضا عنه - صلى الله عليه وسلم - (( إن من كان قبلكم كانوا يتخذون القبور مساجد أفلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك )) ، وفي مسند الإمام أحمد وصحيح ابن حبان عنه - صلى الله عليه وسلم - (( لعن الله زوارات القبوروالمتخذين عليها المساجد والسرج )) ، وقال - صلى الله عليه وسلم - (( إن من كان قبلكم كانوا إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً وصوروا فيه تلك الصور أولئك شرار الخلق عند الله )) .\rأقسام الناس في زيارة القبور:\rوالناس في هذا الباب ( أعني زيارة القبور ) ، على ثلاثة أقسام :\r- قوم يزورون الموتى فيدعون لهم وهذه الزيارة الشرعية .\r- وقوم يزورونهم يدعون بهم ، فهؤلاء هم المشركون في الألوهية والمحبة ."], [9, "- وقوم يزورونهم فيدعونهم أنفسهم ، وقد قال النبي - صلى الله عليه وسلم - (( اللهم لا تجعل قبري وثنا يعبد )) وهؤلاء هم المشركون في الربوبية ، وقد حمى النبي - صلى الله عليه وسلم - جانب التوحيد أعظم حماية تحقيقا لقوله تعالى }إِيَّاكَ نَعْبُد {حتى نهى عن الصلاة في هذين الوقتين لكونه ذريعة إلى التشبه بعبّاد الشمس الذين يسجدون لها في هاتين الحالتين ، وسد - صلى الله عليه وسلم - الذريعة بأن مَنَعَ الصلاة بعد العصر والصبح لاتصال هذين الوقتين اللذين يسجد المشركون فيهما للشمس .\r\rالسجود لغير الله\rوأما السجود لغير الله فقد قال - صلى الله عليه وسلم - (( لا ينبغي لأحد أن يسجد لأحد إلا الله )) ، ولا ينبغي في كلام الله ورسوله إنما يستعمل للذي هو في غاية الإمتناع كقوله تعالى } وَمَا يَنْبَغِي لِلرَّحْمَنِ أَنْ يَتَّخِذَ وَلَدا{ً \"مريم:92\" ، وقوله تعالى }وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنْبَغِي لَهُ{\" يّس: من الآية69\"، وقوله تعالى } وَمَا تَنَزَّلَتْ بِهِ الشَّيَاطِينُ ،وَمَا يَنْبَغِي لَهُمْ{\"الشعراء: من الآية210و211\"، وقوله تعالى }مَا كَانَ يَنْبَغِي لَنَا أَنْ نَتَّخِذَ مِنْ دُونِكَ مِنْ أَوْلِيَاءَ{ \"الفرقان: من الآية18\".\rمن الشرك الحلف بغير الله :\rومن الشرك بالله تعالى المباين لقوله تعالى }إِيَّاكَ نَعْبُد { الشرك به في اللفظ كالحلف بغيره ، كما رواه الإمام أحمد وأبو داود عنه - صلى الله عليه وسلم - أنه قال (( من خلف بغير فقد أشرك )) صححه الحاكم وابن حبان . قال ابن حبان أخبرنا الحسن وسفيان ثنا عبد الله بن عمر الجعفي ثنا عبد الرحمن بن سليمان عن الحسن بن عبد الله النخعي عن سعيد ابن عبيدة قال كنت عند ابن عمر - رضي الله عنه - فحلف رجل بالكعبة فقال ابن عمر - رضي الله عنه - (( وحيك ! لا تفعل ، فإني سمعت رسول الله - صلى الله عليه وسلم - يقول (( من حلف بغير الله فقد أشرك )) ."], [10, "وصور من الإشراك نَحذَرُها :\rومن الإشراك قول القائل لأحد من الناس : ما شاء الله وشئت ، كما ثبت عن النبي - صلى الله عليه وسلم - أنه قال لرجل ( ما شاء الله وشئت ) ، فقال :(( أجعلتني لله ندا ؟ قل ما شاء الله وحده )) هذا من أن الله تعالى قد أثبت للعبد مشيئة كقوله تعالى }لِمَنْ شَاءَ مِنْكُمْ أَنْ يَسْتَقِيمَ{ \"التكوير:28\"، فكيف بمن يقول : أنا متوكل على الله وعليك ، وأنا في حَسَبِ الله وحَسَبِكَ ، ومالي إلا الله وأنت ، وهذا من الله ومنك ، وهذا من بركات الله وبركاتك والله لي في السماء وأنت لي في الأرض ، وازن بين هذه الألفاظ الصادرة من غالب الناس اليوم وبين ما نهى عنه - صلى الله عليه وسلم - من ماشاءَ الله وشئت ، ثم انظر أيها أفحش ، يتبين لك أن قائلها أولى بالبعد من }إِيَّاكَ نَعْبُد { وبالجواب من النبي - صلى الله عليه وسلم - لقائل تلك الكلمة وأنه إذا كان قد جعل رسول الله - صلى الله عليه وسلم - نداً فهذا قد جعل من لا يدانيه لله نداً .\r\rبيان لمعنى العبادة :\rوبالجملة ، فالعبادة المذكورة في قوله تعالى}إِيَّاكَ نَعْبُد { هي السجود ، والتوكل ، والإنابة ، والتقوى ، والخشية ، والتوبة ، والنذور ، والحلف ، والتسبيح ، والتكبير ، والتهليل ، والتحميد ، والاستغفار ، وحلق الرأس خضوعاً وتعبداً والدعاء .. كل ذلك محض حق الله تعالى . وفي مسند الإمام أحمد (( أن رجلاً أتى النبي - صلى الله عليه وسلم - قد أذنب ذنباً ، فلما وقف بين يديه قال : (( اللهم إني أتوب إليك ولا أتوب إلى محمد ، فقال - صلى الله عليه وسلم - : (( عرف الحق لأهله )) . وأخرجه الحاكم من حديث الحسن عن الأسود بن سريع ، وقال حديث صحيح .\r\rتقسيم الشرك إلى تعطيل وغيره وأقسامه\r\rالشرك في الإرادات والنيات :"], [11, "وأما الشرك في الإرادات والنيات ، فذلك البحر الذي لا ساحل له وقلّ من ينجو منه ، فمن نوى بعمله غير وجه الله تعالى فلم يقم بحقيقة قوله }إِيَّاكَ نَعْبُد { فإن }إِيَّاكَ نَعْبُد { هي الحنيفية ملة ابراهيم التي أمر الله بها عباده كلهم ، ولا يقبل من أحد غيرها ، وهي حقيقة الإسلام }وَمَنْ يَبْتَغِ غَيْرَ الْأِسْلامِ دِيناً فَلَنْ يُقْبَلَ مِنْهُ وَهُوَ فِي الْآخِرَةِ مِنَ الْخَاسِرِينَ{ \"آل عمران:85 \" فاستمسك بهذا الأصل ورد ما أخرجه المبتدعة والمشركون إليه تحقق معنى كلمة الإلهية . فإن قيل المشرك إنما قصد تعظيم جناب الله تعالى وأنه لعظمته لا ينبغي الدخول عليه إلا بالوسائط والشفعاء كحال الملوك . فالمشرك لم يقصد الاستهانة بجناب الربوبية ، وإنما قصد تعظيمه وقال }إِيَّاكَ نَعْبُد { ، وإنما أعبد هذه الوسائط لتقربني إليه وَتَدخُلَ بي عليه ، فهو الغاية ، وهذه وسائل ، فَلِمَ كان هذا القدر موجباً لسخط الله تعالى وغضبه ، ومخلداً في النار وموجباً لسفك دماء أصحابه واستباحة حريمهم وأموالهم ؟ وهل يجوز في العقل أن يشرع الله تعالى لعباده التقرب إليه بالشفعاء والوسائط فيكون تحريم هذا إنما استفيد بالشرع فقط أم ذلك قبيح في الشرع ، والعقل يمنع أن تأتيَ به شريعة من الشرائع ؟ ومالسر في كونه لا يغفر من بين سائر الذنوب كما قال تعالى } إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ{\"النساء: من الآية48\".\rقلنا الشرك شركان .. شرك يتعلق بذات المعبود وأسمائه وصفاته وأفعاله ، وشرك في عبادته ومعاملته وإن كان صاحبه يعتقد أنه سبحانه وتعالى لا شريك له في ذاته ولا في صفاته . وأما الشرك الثاني فهو الذي فرغنا من الكلام فيه وأشرنا إليه الآن ، وسنشبع الكلام فيه إن شاء الله تعالى .\r\rتوضيح للشرك في الذات والأسماء والصفات والأفعال :"], [12, "أما الشرك الأول فهو نوعان : أحدهما شرك التعطيل ، وهو أقبح أنواع الشرك ، كشرك فرعون في قوله} وَمَا رَبُّ الْعَالَمِينَ {\"الشعراء: من الآية23\" وقال }يَا هَامَانُ ابْنِ لِي صَرْحاً لَعَلِّي أَبْلُغُ الْأَسْبَاب ، أَسْبَابَ السَّمَاوَاتِ فَأَطَّلِعَ إِلَى إِلَهِ مُوسَى وَإِنِّي لَأَظُنُّهُ كَاذِباً { \"غافر36و37\" والشرك والتعطيل متلازمان ، فكل مشرك معطل ، وكل معطل مشرك ، لكن الشرك لا يستلزم أصل التعطيل بل قد يكون المشرك مقراً بالخالق سبحانه وتعالى وصفاته ، ولكنه مُعَطًّله حق التوحد .\r\rالتعطيل أصل الشرك ومفّسرٌ له :\rوأصل الشرك وقاعدته التي يرجع إليها هو التعطيل وهو ثلاثة أقسام :\rأحدها : تعطيل المصنوع عن صانعه .\rالثاني : تعطيل الصانع عن كماله الثابت له .\rالثالث : تعطيل معاملته عما يجب على العبد من حقيقة التوحيد ...\rومن هذا شرك أهل الوحدة ومنه شرك الملاحدة القائلين بِقَدَم العالم وأبديته وأن الحوادث بأسرها مستندة إلى أسباب ووسائط اقتضت إيجادها ، ويسمونها العقول والنفوس ، ومنه شرك معطلة الأسماء والصفات كالجهمية والقرامطة وغلاة المعتزلة.\r\rتوضيح لشرك من جعل مع الله إلها آخر :\rالنوع الثاني شرك التمثيل ، وهو شرك من جعل "]], "pg": [1, 12]}, "ص109.2": {"x": [[12, "معه إلها آخر ، كالنصارى في المسيح واليهود في عزير ، والمجوس القائلين بإسناد حوادث الخير إلى النور وحوادث الشر إلى الظلمة . والقدرية المجوسية مختصر منه ، وهؤلاء أكثر مشركي العالم ، وهم طوائف جمة منهم من يعبد أجزاء سماوية ، ومنهم من يعبد أجزاء أرضية ، ومن هؤلاء من يزعم أن معبوده أكبر الآلهة ، ومنهم من يزعم أنه إذا خصه بعبادته والتبتل إليه أقبل إليه واعتنى به ، ومنهم من يزعم أن معبوده الأدنى يقربه إلى الأعلى الفوقاني والفوقاني يقربه إلى من هو فوقه حتى تقربه تلك الآلهة إلى الله سبحانه وتعالى ، فتارة تكثر الوسائط وتارة تقل ."], [13, "فإذا عرفت هذه الطوائف وعرفت اشتداد نكير الرسول - صلى الله عليه وسلم - على من أشرك به تعالى في الأفعال والأقوال والإرادات كما تقدم ذكره ، انفتح لك باب الجواب عن السؤال . فتقول : أعلم أن حقيقة الشرك تشبيه الخالق بالمخلوق ، وتشبيه المخلوق بالخالق .\rأما الخالق فإن المشرك شبه المخلوق بالخالق في خصائص الإلهية ، وهي التفرد بملك الضر والنفع والعطاء والمنع ، فمن علق ذلك بمخلوق فقد شبهه بالخالق تعالى سوى بين التراب ورب الأرباب ، فأي فجور وذنب أعظم من هذا ؟.\r\rمن خصائص الإلهية الكمال المطلق\rومن خصائص الإلهية :\rواعلم خصائص الإلهية الكمال المطلق من جميع الوجوه الذي لا نقص فيه بوجه من الوجوه ، وذلك يوجب أن تكون العبادة له وحده عقلا وشرعاً وفطرة ، فمن جعل ذلك لغيره ، فقد شبه الغير بمن لا شبيه له ، ولشدة قبحه وتضمنه غاية الظلم ، أخبر من كتب على نفسه الرحمة أنه لا يغفره أبداً ، ومن خصائص الإلهية ، العبودية التي لا تقوم إلا على ساق الحب والذل ، فمن أعطاهما لغيره ، فقد شبهه بالله سبحانه وتعالى في خالص حقه ، وقبح هذا مستقر في العقول والفطر ، لكن لما غيرت الشياطين فطر أكثر الخلق واجتالتهم عن دينهم وأمرتهم أن يشركوا بالله ما لم ينزل به سلطاناً – كما رَوى ذلك عن الله أعرف الخلق به وبخلقه – عَمُوا عن قبح الشرك حتى ظنوه حسناً ، ومن خصائص الإلهية السجود ، فمن سجد لغيره فقد شبهه به ، ومنها التواكل ، فمن توكل على غيره فقد شبهه به , ومنها التوبة ، فمن تاب لغيره فقد شبهه به ، ومنها الحلف باسمه فمن حلف بغيره فقد شبهه به . ومنها الذبح له ، فمن ذبح لغيره فقد شبهه به . ومنها حلق الرأس .. إلى غير ذلك .\r\rمن تشبه بالله قصمه الله :"], [14, "هذا في جانب التشبيه ، وأنا في جانب التشبه ، فمن تعاظم وتكبر ودعا إلى اطرائه ورجائه ومخافته فقد تشبه بالله ونازعه في ربوبيته وهو حقيق بأن يهينه الله غاية الهوان ، ويجعله كالذر تحت أقدام خلقِهِ وفي الصحيح عنه - صلى الله عليه وسلم - أنه قال (( يقول الله عز وجل : العظمة إزاري ، والكبرياء ردائي ، فمن نازعني في واحد منهما عذبته )) . وإذا كان المصور الذي يصنع الصور بيده من أشد الناس عذاباً يوم القيامه لتشبهه بالله في مجرد الصنعة ، فما الظن بالمشبه بالله في الربوبية والإلهية كما قال - صلى الله عليه وسلم - (( أشد الناس عذاباً يوم القيامة المصورون يقال لهم أحيوا ما خلقتم )) وفي الصحيح عنه - صلى الله عليه وسلم - أنه قال : يقول الله - عز وجل - : ومن أظلم ممن ذهب يخلق كخلقي فليخلقوا ذرة فليخلقوا شعيرة )) فنبه بالذرة والشعيرة على ما هو أعظم منها وكذلك من تشبه به تعالى في الاسم الذي لا ينبغي إلا له كملك الملوك وحاكم الحكام وقاضي القضاة ونحوه .. فقد ثبت عن النبي - صلى الله عليه وسلم - أنه قال (( إن أخنع الأسماء عند الله رجل تسمى بشاهان شاه ( ملك الملوك ) لا مالك إلا الله )) . وفي لفظ (( أغيظ رجل عند الله رجل تسمى ملك الأملاك )) .\r\rالتشبيه والتشبه هو حقيقة الشرك :\rوبالجملة ، فالتشبيه والتشبه هو حقيقة الشرك ولذلك كان من ظن أنه إذا تقرب إلى غيره بعبادة ما يقربه ذلك الغير إليه تعالى فإنه يخطئ لكونه شبهه به وأخذ مالاً ينبغي أن يكون إلا له . فالشرك منعه سبحانه وتعالى حقه فهذا قبيح عقلا وشرعاً ، ولذلك لم يشرع ولم يغفر له .\r\rاتخاذ الشفعاء إساءة بالغة :\rواعلم أن الذي ظن أن الرب سبحانه وتعالى لا يسمع له أو لا يستجيب له إلا بواسطة تطلعه على ذلك أو تسأل ذلك منه فقد ظن بالله ظن السوء فإنه إن ظن أنه لا يعلم أو لا يسمع إلا بإعلام غيره له وإسماعه فذلك نفي لعلم الله وسمعه وكمال إدراكه وكفى بذلك ذنباً ."], [15, "وإن ظن أنه يسمع ويرى ولكن يحتاج إلى من يُلَيِّنُهُ ويُعَطِّفُهُ عليهم فقد أساء الظن بإفضال ربه وبره وإحسانه وسعة وجوده . وبالجملة ، فأعظم الذنوب عند الله تعالى إساءة الظن به أعظم وعيد ، كما قال الله تعالى} الظَّانِّينَ بِاللَّهِ ظَنَّ السَّوْءِ عَلَيْهِمْ دَائِرَةُ السَّوْءِ وَغَضِبَ اللَّهُ عَلَيْهِمْ وَلَعَنَهُمْ وَأَعَدَّ لَهُمْ جَهَنَّمَ وَسَاءَتْ مَصِيراً{\"الفتح: من الآية6\" ، وقال تعالى عن خليله ابراهيم عليه السلام }أَإِفْكاً آلِهَةً دُونَ اللَّهِ تُرِيدُونَ ،فَمَا ظَنُّكُمْ بِرَبِّ الْعَالَمِينَ{ \"الصافات86و87\" أي : فما ظنكم أن يجازيكم إذا عبدتم معه غيره وظننتم أنه يحتاج في الإطلاع على ضرورات عباده لمن يكون بابا للحوائج إليه ونحو ذلك . وهذا بخلاف الملوك فإنهم محتاجون إلى الوسائط ضرورة لحاجتهم وعجزهم وضعفهم وقصور علمهم عن إدراك حوائج المضطرين . فأما من لا يشغله سمعٌ عن سمع ، وسبقت رحمته غضبه وكتب على نفسه الرحمة فما تصنع الوسائط عنده فمن اتخذ واسطة بينه وبين الله تعالى فقد ظن به أقبح الظن ، ومستحيل أن يشرعه لعباده بل ذلك يمتنع في العقول والفطر .\r\rعدم جواز الخضوع والتأله"], [16, "واعلم أن الخضوع والتأله الذي يجعله العبد لتلك الوسائط قبيح في نفسه ، كما قررناه لا سيما إذا كان المجعول له ذلك عبداً للملك العظيم الرحيم القريب المجيب ومملوكاً له كما قال تعالى }ضَرَبَ لَكُمْ مَثَلاً مِنْ أَنْفُسِكُمْ هَلْ لَكُمْ مِنْ مَا مَلَكَتْ أَيْمَانُكُمْ مِنْ شُرَكَاءَ فِي مَا رَزَقْنَاكُمْ فَأَنْتُمْ فِيهِ سَوَاءٌ تَخَافُونَهُمْ كَخِيفَتِكُمْ أَنْفُسَكُمْ {\"الروم: من الآية28\" أي إذا كان أحدكم يأنف أن يكون مملوكه في شريكه في رزقه ، فكيف تجعلون لي من عبيدي شركاء فيما أنا منفرد به وهو الإلهية التي لا تنبغي لغيري ولا تصلح لسواي ، فمن زعم ذلك فما قدرني حق قدري ولا عظمني حق تعظيمي ؛ وبالجملة فما قدره حق قدره من عبد معه من ظن أن يوصل إليه ، قال تعالى }يَا أَيُّهَا النَّاسُ ضُرِبَ مَثَلٌ فَاسْتَمِعُوا لَهُ إِنَّ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللَّهِ لَنْ يَخْلُقُوا ذُبَاباً{ \"الحج: من الآية73\" الآية .. إلى أن قال } مَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ{ \"الحج:74\" وقال تعالى }وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعاً قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ{ \"الزمر:67\".\rفما قَدَرَ القوي العزيز حق قدره من أشرك معه الضعيف الذليل .\r\rأصل ضلال الطوائف الضالة :"], [17, "واعلم أنك إذا تأملت جميع طوائف الضلال والبدع وجدت أصل ضلالهم راجعاً إلى شيئين : أحدهما الظن بالله ظن السوء ، والثاني لم يقدروا الرب حق قدره ، فلم يقدره حق قدره من ظن أنه لم يرسل رسولاً ولا أنزل كتاباً بل ترك الحلق سدىً وخلقهم عبثاً ، ولا قدره حق قدره من نفى عموم قدرته وتعلقها بأفعال عباده من طاعتهم ومعاصيهم وأخرجهما عن خلقه وقدرته ، ولا قدر الله حق قدره أضداد هؤلاء الذين قالوا إنه يعاقب عبده على ما لم يفعله بل يعاقبه على فعله سبحانه وتعالى وإذا استحال في العقول أن يجبر السيد عبده على فعل ثم يعاقبه عليه فكيف يصدر هذا من أعدل العادلين . وقول هؤلاء شر من أشباه المجوس القدرية الأذلين ، ولا قدره حق قدره ، من نفى رحمته ورضاه ومحبته وغضبه وحكمته مطلقا وحقيقة قعله ، ولم يجعل له فعلا اختياريا ، بل أفعاله مفعولات منفصله عنه . ولا قدره حق قدره من جعل له صاحبة وولداً أو جعله يحل في مخلوقاته أو جعله عين هذا الوجود . ولا قدره حق قدره من قال إنه رفع أعداء رسوله وأهل بيته وجعل فيهم الملك ووضع أولياء رسوله وأهل بيته وهذا يتضمن غاية القدح في الرب تعالى الله عن قول الرافضة . وهذا مشتق من قول اليهود والنصارى في قول رب العالمين : إنه أرسل ملكا ظالما فادعى النبوة وكذب على الله ، ومكث زمناً طويلاً يقول أمرني بكذا ونهاني عن كذا ويستبيح دماء أبناء الله وأحبائه والرب تعالى يظهره ويؤيده ويقيم الأدلة والمعجزات على صدقه ويقبل بقلوب الخلق وأجسادهم إليه ، ويقيم دولته على الظهور والزيادة ويذل الرافضة ، تجد القولين سواء ، ولا قدره حق قدره من زعم أنه لا يحيي الموتى ولا يبعث من في القبور ليبين لعباده الذي كانوا فيه يختلفون وليعلم الذين كفروا أنهم كانوا كاذبين .\r\rعابد غير الله إنما يعبد الشيطان :"], [18, "وبالجملة ، فهذا باب واسع ، والمقصود أن كل من عبد مع الله غيره فإنما عبد شيطاناً . قال تعالى } أَلَمْ أَعْهَدْ إِلَيْكُمْ يَا بَنِي آدَمَ أَنْ لا تَعْبُدُوا الشَّيْطَانَ{\"يّس: من الآية60\" . فما عبد أحدٌ أحداً من بني آدم كائناً من كان إلا وقد وقعت عبادته للشيطان فيستمتع العابد بالمعبود في حصول غرضه ، ويستمتع المعبود بالعابد في تعظيمه له وإشراكه مع الله تعالى وذلك غاية رضى الشيطان . ولهذا قال تعالى} وَيَوْمَ يَحْشُرُهُمْ جَمِيعاً يَا مَعْشَرَ الْجِنِّ قَدِ اسْتَكْثَرْتُمْ مِنَ الْأِنْسِ{\"الأنعام: من الآية128\" أي من إغوائهم وإضلالهم} وَقَالَ أَوْلِيَاؤُهُمْ مِنَ الْأِنْسِ رَبَّنَا اسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَا أَجَلَنَا الَّذِي أَجَّلْتَ لَنَا قَالَ النَّارُ مَثْوَاكُمْ خَالِدِينَ فِيهَا إِلَّا مَا شَاءَ اللَّهُ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ)\"الأنعام: من الآية128\" فهذه إشارة لطيفة إلى السر الذي لأجله كان الشرك أكبر الكبائر عند الله وأنه لا يُغفر بغير التوبة منه ، وأنه موجب للخلود في العذاب العظيم ، وأنه ليس تحريمه قبحه بمجرد النهي عنه فقط ، بل يستحيل على الله سبحانه وتعالى أن يشرع لعباده عبادة إلهٍِ غيره كما يستحيل على ما يناقض أوصاف كماله ونعوت جلاله .\r\rتقسيم العبادة من حيث الإستعانة\rأقسام الناس في عبادة الله :"], [19, "وأعلم أن الناس في عبادة الله تعالى والاستعانة به أقسام : أجلها وأفضلها أهل العبادة والاستعانة بالله عليها ، فعبادة الله غاية مرادهم ، وطلبهم منه أن يعينهم عليها ويوفقهم للقيام بها نهاية مقصودهم ، ولهذا كان أفضل ما يسأل الرب تعالى الإعانة على مرضاته ، وهو الذي علمه النبي - صلى الله عليه وسلم - لمعاذ بن جبل فقال (( يا معاذ ، والله إني أحبك فلا تدع أن تقول في كل دبر صلاة : اللهم أعني على ذكرك وشرك وحسن عبادتك )) فانفع الدعاء طلب العون على مرضاته تعالى : ويقابل هؤلاء القسم الثاني ، المعرضون عن عبادته والاستعانة به ، فلا عبادة لهم ولا استعانة ، بل إن سأله تعالى أحدهم واستعان به فعلى حظوظه وشهواته والله سبحانه وتعالى يسأله من في السماوات والأرض ويسأله أولياؤه وأعداؤه فيمد هؤلاء وهؤلاء ، وأبغض خلق الله إبليس ، ومع هذا أجاب سؤله وقضى حاجته ومتعه بها ، ولكن لما لم تكن عوناً على مرضاته كانت زيادة في شقوته وبعده . وهكذا كل من سأله تعالى واستعان به على مالم يكن عوناًً له على طاعته كان سؤاله مبعداً له عن الله فليتدبر العاقل هذا وليعلم أن إجابة الله لسؤال بعض السائلين ليست لكرامته عليه بل قد يسأله عبده الحاجة فيقضيها له وفيها هلاكه ، ويكون منعه حماية له وصيانة ، والمعصوم من عصمه الله . والإنسان على نفسه بصيرة .\r\rالإكرام والإهانة بالتقوى أو عدمها :"]], "pg": [12, 19]}, "ص109.3": {"x": [[20, "وعلامة هذا أنك ترى من صانه الله من ذلك وهو يجهل حقيقة الأمر إذا رآه سبحانه وتعالى يقضي حوائج غيره يسئ ظنه به تعالى وقلبه محشو بذلك وهو لا يشعر ، وأمارة ذلك حمله على الأقدار وعتابه في الباطن لها ، ولقد كشف الله تعالى هذا المعنى غاية الكشف في قوله تعالى }فَأَمَّا الْأِنْسَانُ إِذَا مَا ابْتَلاهُ رَبُّهُ فَأَكْرَمَهُ وَنَعَّمَهُ فَيَقُولُ رَبِّي أَكْرَمَنِ ، وَأَمَّا إِذَا مَا ابْتَلاهُ فَقَدَرَ عَلَيْهِ رِزْقَهُ فَيَقُولُ رَبِّي أَهَانَن ، كلا { \"الفجر15و17\". أي ليس كل من أعطيته ونعمته وخوّلته فقد أكرمته وماذاك لكرامته عليّ ولكنه ابتلاء مني وامتحان له أيشكرني فأعطيه فوق ذلك أم يكفرني فأسلبه إياه وأحوله عنه لغيره ، وليس كل من ابتليته فضيقت عليه رزقه وجعلته بقدر لا يفضل عنه فذاك من هوانه عليّ ولكن ابتلاء وامتحان له مني ، أيصبر فأعطيه أضعاف ما فاته أم يسخط فيكون حظه من السخط .\rوبالجملة فأخبر تعالى أن الإكرام والإهانة لا يدوران على المال وسعة الرزق وتقديره فإنه سبحانه وتعالى يوسع على الكافر لا لكرامته ويقتر على المؤمن لا لهوانه عليه ، وإنما يكرم سبحانه وتعالى من يكرم من عباده بأن يوفقه لمعرفته ومحبته وعبادته واستعانته . فغاية سعادة الأبد في عبادة الله والاستعانة به عليها .\rالقسم الثالث من له نوع عبادة بلا استعانة .. وهؤلاء نوعان : أحدهما أهل القدر القائلون : بأنه سبحانه وتعالى قد فعل بالعبد جميع مقدروه من الألطاف وأنه لم يبق في مقدروه إعانة له على الفعل فإنه قد أعانه بخلق الآلات وسلامتها وتعريف الطريق ، وإرسال الرسول وتمكينه من الفعل ، فلم يبق بعدها إعانة مقدورة يسألها إياها ، وهؤلاء مخذولون موكولون إلى أنفسهم مسدود عليهم طريق الاستعانة والتوحيد . قال ابن عباس رضي الله عنهما : الإيمان بالقدر نظام التوحيد فمن آمن بالله وكذب بقدره نقض تكذيبه توحيده ."], [21, "النوع الثاني : من لهم عبادة وأوراد ولكن حظهم "]], "pg": [20, 21]}, "ص109.4": {"x": [[21, "ناقص من التوكل والاستعانة لم تتسع قلوبهم لارتباط الأسباب بالقدر ، وأنها بدون المقدور كالموات الذي لا تأثير له بل كالعدم الذي لا وجود له وأن القدر كالروح المحرك لها ، والمعول على المحرك الأول ، فلم تنفذ بصائرهم من السبب إلى المسبب ومن الآلة إلى الفاعل فقل نصيبهم من الاستعانة . وهؤلاء لهم نصيب من التصرف بحسب استعانتهم وتوكلهم ونصيب من الضعف والخذلان بحسب قلة استعانتهم وتوكلهم ونصيب من الضعف والخذلان بحسب قلة استعانتهم وتوكلهم ولو توكل العبد على الله حق توكله في إزالة جبل [ يراد إزالته ] عن مكانه لأزاله .\r\rبيان معنى الاستعانة\rتفسير لحقيقة الاستعانة عملا :\rفإن قيل ما حقيقة الإستعانة عملا ؟ قلنا هي التي يعبر عنها بالتوكل وهي حالة للقلب تنشأ عن معرفة الله تعالى وتفرده بالخلق والأمر والتدبير والضر والنفع وأنه ماشاء كان ومالم يشأ لم يكن فتوجب اعتماداً عليه وتفويضاً إليه وثقة به فتصير نسبة العبد إليه تعالى كنسبة الطفل إلى أبويه فيما ينوبه من رغبته ورهبته ، فلو دهمه ما عسى أن يدهَمَهُ إلى الآفات لم يلتجئ إلى غيرها . فإن كان العبد مع هذا الاعتماد من أهل التقوى كانت له العاقبة الحميدة} وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجاً)وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ وَمَنْ يَتَوَكَّلْ عَلَى اللَّهِ فَهُوَ حَسْبُهُ{\"الطلاق2و3) أي كافيه .\rالقسم الرابع : من له استعانة بلا عبادة وتلك "]], "pg": [21, 21]}, "ص109.5": {"x": [[21, "حالة من شهد تفرد الله بالضر والنفع ولم يدر بما يحبه ويرضاه فتوكَّل عليه في حظوظه فأسعفه بها سواء كانت أموالاً أو رياسات أو جاهاً عند الخلق أن نحو ذلك ، وهذا لا عاقبة له ، فذلك حظه من دنياه وآخرته .\r\rالإخلاص والاتباع بهما النجاة :"], [22, "واعلم أن العبد لا يكون متحققا بعبادة الله تعالى إلا بأصلين : أحدهما متابعة الرسول - صلى الله عليه وسلم - ، والثاني إخلاص العبودية . والناس في هذين الأصلين على أربعة أقسام :\rالضرب الأول : أهل الإخلاص والمتابعة .. فأعمالهم كلها لله وأقوالهم منعهم وإعطاؤهم وحبهم وبغضهم كل ذلك لله تعالى لا يريدون من العباد جزاءً ولا شكواً ، عدُّوا الناس كأصحاب القبور لا يملكون ضراً ولا نفعاً ولا موتاً ولا حياةً ولا نشوراً فإنه لا يعامل أحداً من الخلق إلا لجهله بالله وجهله بالخلق . والإخلاص هو العمل الذي لا يقبل الله من عاملٍ عملاً صواباً عارياً منه ، وهو الذي ألزم عباده به إلى الموت . قال الله تعالى} لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلاً{\"الملك: من الآية2\" وقال}إِنَّا جَعَلْنَا مَا عَلَى الْأَرْضِ زِينَةً لَهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلاً{ \"الكهف:7\" ، وأحسن العمل أخلصه وأصوبه . فالخالص أن يكون لله ، والصواب أن يكون على وفق سنة رسول الله - صلى الله عليه وسلم - ،وهذا هو العمل الصالح المذكور في قوله تعالى}وَمَنْ أَحْسَنُ دِيناً مِمَّنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ{\"النساء: من الآية125\" وهو العمل الحسن في قوله تعالى} فَمَنْ كَانَ يَرْجُوا لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلاً صَالِحاً{\"الكهف: من الآية110\" وهو الذي أمر به النبي - صلى الله عليه وسلم - في قوله (( كل عمل ليس عليه أمرنا فهو رد )) ، وكل عمل بلا متابعة فإنه لا زيد عامله إلا بعداً من الله تعالى ، فإن الله تعالى إنما يعبد بأمره لا بالأهواء والآراء .\r\rشرار الخلق :"], [23, "الضرب الثاني : من لا إخلاص له ولا متابعة له وهؤلاء شرار الخلق وهم المتزيّنون بأعمال الخير يراءون بها الناس ، وهذا الضرب يكثر فيمن انحرف عن الصراط المستقيم من المنتسبين إلى الفقه والعلم والفقر والعبادة فإنهم يرتكبون البدع والضلال والرياء والسمعة ويحبون أن يحمدوا بما لم يفعلوا . وفي أضراب هؤلاء نزل قوله تعالى}لا تَحْسَبَنَّ الَّذِينَ يَفْرَحُونَ بِمَا أَتَوْا وَيُحِبُّونَ أَنْ يُحْمَدُوا بِمَا لَمْ يَفْعَلُوا فَلا تَحْسَبَنَّهُمْ بِمَفَازَةٍ مِنَ الْعَذَابِ وَلَهُمْ عَذَابٌ أَلِيمٌ{ \"آل عمران:188\".\r\rالغلو مع عدم المتابعة يضر العابد :\rالضرب الثالث : من هو مخلص في أعماله لكنها على غير متابعة الأمر ، كجهال العباد والمنتسبين إلى الزهد والفقر وكل من عبد الله على غير مراده ؛ والشأن ليس في عبادة الله فقط : بل في عبادة الله كما أراد الله . ومنهم من يمكث في خلواته تاركاً للجمعة ، ويرى ذلك قربةً وأمثال ذلك .\r\rوالرياء محبط للعبادات :\rالضرب الرابع : من أعماله على متابعة الأمر ، لكنها لغير الله تعالى كطاعات المرائين ، وكالرجل يقاتل رياء وسمعة وحمية وشجاعة وللمغنم ، ويحج ليقال ، ويقرأ ليقال ، ويُعَلِّم ويؤلف ليقال ، فهذه أعمال صالحة لكنها غير مقبولة ؛ قال تعالى}وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاء{\"البينة:من الآية5\" فلم يؤمر الناس إلا بالعبادة على المتابعة والإخلاص فيها ، والقائم بهما هم أهل}إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ{.\r\rصور من الغلو وأخذ الشريعة من جهة واحدة:\rثم أهل مقام }إِيَّاكَ نَعْبُدُ{لهم في أفضل العبادة وأنفعها وأحقها بالإيثار والتخصيص أربعة طرق ، وهم في ذلك أربعة أصناف .\r\rأهل المشقة على النفوس :"], [24, "الصنف الأول : عندهم أنفع العبادات وأفضلها أشقها على النفوس وأصعبها ، قالوا لأنه أبعد الأشياء من هواها وهو حقيقة التعبد ، والأجر على قدر المشقة ،ورووا حديثا ليس له أصل (( أفضل الأعمال أحمزها )) ، أي أصعبها وأشقها ، وهؤلاء هم أرباب المجاهَدات والجور على النفوس ، قالوا وإنما تستقيم النفوس بذلك ، إذ طبعها الكل والمهاونة والإخلاد إلى الراحة فلا تستقيم النفوس بذلك إلا بركوب الأهوال وتحمل المشاق .\r\rأهل الزهد في متاع الدنيا :\rالصنف الثاني : قالوا أفضل العبادات وأنفعها التجرد والزهد في الدنيا والتقلل منها غاية الإمكان واطراح الاهتمام بها ، وعدم الاكتراث لما هو منها .\rعوام الزهاد وخواصهم :\rثم هؤلاء قسمان : فعوامهم ظنوا أن هذا غاية فشمروا إليه وعملوا عليه وقالوا : هو أفضل من درجة العلم والعبادة ورأوا الزهد في الدنيا غاية كل عبادة ورأسها ، وخواصهم رأوا هذا مقصوداً لغيره وأن المقصود به عكوف القلب على الله تعالى والاستغراق في محبته والإنابة إليه والتوكل عليه والاشتغال بمرضاته ، فرأوا أفضل العبادات دوام ذكره بالقلب واللسان ثم هؤلاء قسمان ، فالعارفون إذا جاء الأمر والنهي بادروا إليه ولو فرقهم وأذهب جمعهم والمنحرفون منهم يقولون المقصود من القلب جَمعِيًّتُه فإذا جاء ما يفرقه عن الله لم يلتفتوا إليه ويقولون :\rيطالب بالأوراد من كان غافلاً فكيف بقلب كل أوقاته وِرد\rمن آفات الغلو في أخذ الشريعة من جهة واحدة :\rثم هؤلاء أيضا قسمان : منهم من يترك الواجبات والفرائض لجمعيَّته : ومنهم من يقول بها ويترك السنن والنوافل ويعلم العلم النافع لجمعيَّته .\rوالحق أن الجمعية حظ القلب ، وإجابة داعي الله حق الرب ، فمن آثر حق نفسه على حق ربه فليس من العبادة في شيءٍ.\rأهل قضاء حوائج الناس والنفع المتعدِّي:"], [25, "الصنف الثالث : رأوا أن أفضل العبادات ماكان فيه نفع متعد فرأوه أفضل من النفع القاصر فرأوا خدمة الفقراء والاشتغال بمصالح الناس وقضاء حوائجهم ومساعدتهم بالجاه والمال والنفع لقوله - صلى الله عليه وسلم - (( الخلق عيال الله وأحبهم إلى الله أنفعهم لعياله )) . قالوا : وعمل العابد قاصر على نفسه وعمل النفاع متعدٍّ إلى الغير ، فأين أحدهما من الآخر ؟ ، ولهذا كان فضل العالم العابد كفضل القمر ليلة البدر على سائر الكواكب . وقد قال - صلى الله عليه وسلم - لعلي (( لأن يهدي الله بك رجلا واحدا خير لك من حُمُر النعم ))وقال - صلى الله عليه وسلم - (( من دعا إلى هدىً كان له من الأجر مثل أجور من تبعه من غير أن ينقص من أجورهم شيئاً)) ، وقال - صلى الله عليه وسلم - (( إن العالم يستغفر له من في السماوات ومن في الأرض حتى الحيتان في البحر والنملة في جحرها )) ، قالوا ، وصاحب العبادة إذا مات انقطع عمله ، وصاحب النفع لا ينقطع عمله مادام نفعه الذي تسبب فيه . والأنبياء عليهم الصلاة والسلام إنما بعثوا بالإحسان إلى الخلق وهدايتهم ونفعهم في معاشهم ومعادهم ولم يبعثوا بالخلوات والانقطاع ، ولهذ انكر النبي - صلى الله عليه وسلم - على أولئك النفر الذين هموا بالانقطاع والتعبد وترك مخالطة الناس ، ورأى هؤلاء أن التفرغ لنفع الخلق أفضل من الجمعية على الله بدون ذلك قالوا ومن علم ذلك العلم والتعليم ونحو هذه الأمور الفاضلة .\r\rأفضل العبادة الاشتغال في كل وقت بما يناسبه\rأهل التعبد المطلق ومنهاجهم المتكامل :"], [26, "الصنف الرابع : قالوا : أفضل العبادة العمل على مرضاة الرب سبحانه وتعالى واشتغال كل وقت بما هو مقتضى ذلك الوقت ووظيفته ، فأفضل العبادات في وقت الجهاد الجهاد وإن آل إلى ترك الأوراد من صلاة الليل وصيام النهار ، بل من ترك إتمام صلاة الفرض كما في حالة الأمن والأفضل في وقت حضور الضيف القيام بحقه والاشتغال به . والأفضل في وقت السحر الاشتغال بالصلاة والقرآن والذكر والدعاء ، والأفضل وقت الآذان ترك ما هو فيه من الأوراد والاشتغال بإجابة المؤذن . والأفضل في أوقات الصلوات الخمس الجد والاجتهاد في إيقاعها على أكمل الوجوه والمبادرة إليها في أول الوقت والخروج إلى المسجد وإن بعد . والأفضل في أوقات ضرورة المحتاج المبادرة إلى مساعدته بالجاه والمال والبدن . والأفضل في السفر مساعدة المحتاج وإعانة الرفقة وإيثار ذلك على الأوراد والخلوة ."], [27, "والأفضل في وقت قراءة القرآن جمعية القلب والهمة على تدبره والعزم على على تنفيذ أوامره أعظم من جمعية قلب من جاءه كتاب من السلطان على ذلك . والأفضل في وقت الوقوف بعرفة الأجتهاد في التضرع والدعاء والذكر . والأفضل في أيام عشر ذي الحجة الإكثار من التعبد لا سيما التكبير والتهليل والتحميد وهو أفضل من الجهاد الغير المتعين . والأفضل في العشرة الأواخر من رمضان لزوم المساجد والخلوة فيها مع الإعتكاف والإعراض عن مخالطة الناس والاشتغال لهم حتى أنه أفضل من الإقبال على تعليمهم العلم وإقرائهم القرآن عند كثير من العلماء . والأفضل في العشرة عن مخالطة الناس والاشتغال بهم حتى أنه أفضل من الإقبال على تعليمهم العلم وإقرائهم القرآن عند كثير من العلماء . والأفضل في وقت مرض أخيك المسلم أو موته عيادته وحضور جنازته وتشييعه وتقديم ذلك على خلوتك وجمعيتك . والأفضل وقت نزول النوازل وإيذاء الناس لك أداء واجب الصبر مع خلطتك لهم ، والمؤمن الذي لا يخالط الناس ويصبر على أذاهم أو إيذائهم أفضل من المؤمن الذي لا يخالط الناس ولا يصبر على أذاهم . وخلطتهم في الخير أفضل من عزلتهم فيه ، وعزلتهم في الشر أفضل من خلطتهم فيه . فإن علم أنه إذا خالطهم أزاله وقلله ، فخلطتهم خير من اعتزالهم ، وهؤلاء هم أهل التعبد المطلق ، والأصناف التي قبلهم أهل التعبد المقيد ، فمتى خرج أحدهم عن الفرع تعلق به من العبادة وفارقه يرى نفسه كأنه قد نقص ونزل عن عبادته فهو يعبد الله تعالى على وجه واحد وصاحب التعبد المطلق ليس له غرض في تعبد بعينه يؤثره على غيره بل غرضه تتبع مرضاة الله تعالى : إن رأيت العلماء رأيته معهم وكذلك مع الذاكرين ، والمتصدقين وأرباب الجمعية وعطوف القلب على الله ، فهذا هو الغذاء الجامع للسائر إلى الله في كل طريق والوافد عليه مع كل فريق .\r\rمثال ودليل على سلامة وصحة منهج أهل التعبد المطلق :"], [28, "واستحضر ههنا حديث أبي بكر الصديق رضي الله عنه وقول النبي - صلى الله عليه وسلم - بحضوره (( هل منكم أحدٌ أطعم اليوم مسكيناً ؟ ، قال أبو بكر : أنا ، قال : هل منكم أحدٌ أصبح اليوم صائماً ؟، قال أبو بكر : أنا ، قال : هل منكم أحد عاد اليوم مريضاً ؟ ، قال أبو بكر : أنا ، قال : هل منكم أحد اتبع جنازة ؟ ، قال أبو بكر : أنا )) الحديث : هذا الحديث رُوِي عن طريق عبد الغني بن أبي عقيل . حدثنا نُعيم بن سالم عن أنس بن مالك رضي الله عنه قال (( كان رسول الله - صلى الله عليه وسلم - جالساً في جماعة من أصحابه فقال : من صام اليوم ؟ قال أبو بكر : أنا ، قال : من تصدق اليوم ؟ قال أبو بكر : أنا ، قال : من عاد مريضاً اليوم ؟ قال أبو بكر : أنا قال : من شهد اليوم جنازة ؟ قال أبو بكر : أنا ، قال : وجبت لك )) يعني الجنة . ونُعيم بن سالم وإن تكلم فيه لكن تابعه سلمة بن وردان وله أصل صحيح من حديث مالك عن محمد بن شهاب عن حميد ابن عبد الرحمن بن عوف عن أبي هريرة رضي الله عنه (( أن رسول الله - صلى الله عليه وسلم - قال : من أنفق زوجين في سبيل الله نودي في الجنة يا عبد الله هذا خير ، فمن كان من أهل الصلاة نودي من باب الصلاة ، ومن كان من أهل الجهاد نودي من باب الجهاد ، ومن كان من أهل الصدقة دعي من باب الصدقة ومن كان من أهل الصيام دعي من باب الريان ، فقال أبو بكر رضي الله عنه : يا رسول الله ما على من يدعى من هذه الأبواب كلها من ضرورة فهل يدعى أحد من هذه الأبواب كلها ؟ قال : نعم وأرجو أن تكون منهم )) هكذا رواه عن مالك موصولاً مسنداً عن يحيى بن يحيى ومعن ابن عيسى وعبد الله بن المبارك ، ورواه يحيى بن بكير وعبد الله بن يوسف عن مالك عن أبي شهاب عن حُمَيد مرسلاً . وليس هو عند القعنبي لا مرسلاً ولا مسنداً.\rتفسير لكلمة :"], [29, "ومعنى قوله (( من أنفق زوجين )) يعني شيئين من نوع واحد نحو درهمين أو دينارين أو فرسين أو قميصين ، وكذلك من صلى ركعتين أو مشى في سبيل الله تعالى خطوتين أو صام يومين ونحو ذلك ، وإنما أراد – والله أعلم – أقل التكرار وأقل وجوه المداومة على العمل من أعمال البر ، لأن الاثنين أقل الجمع .\rثناء على من يعطى كل ذي حقٍ حقه :\rفهذا كالغيث ، أين وقع نفع ، صحب الله بلا خلق , وصحب الخلق بلا نفس ، إذا كان مع الله عزل الخلائق من البين ، وتخلى عنهم وإذا كان مع خلقه عزل نفسه من الوسط وتخلى عنها ، فما أغربه بين الناس ، وما أشد وحشته منهم ، وما أعظم أنه بالله وفرحه به ، وطمأنينته وسكونه إليه .\r\rللناس في منفعة العبادة طرق أربع\rالمذاهب في بيان حكمة العبادة وعلتها :\rواعلم أن للناس في منفعة العبادة وحكمتها ومقصودها طرقا أربعة وهم في تلك أربعة أصناف : الصنف الأول :نفاة الحِكَم والتعليل الذين يردون الأمر إلى نفس المشيئة وصرف الإرادة ، فهؤلاء عندهم القيام بها ليس إلا لمجرد الأمر من غير أن تكون سببا لسعادة في معاش ولا معاد ولا سببا لنجاة وإنما القيام بها لمجرد الأمر ومحض المشيئة ، كما قالوا في الخلق لم يخلق لغاية ولا لعلة هي المقصودة به ، ولا لحكمة تعود إليه منه ، وليس في المخلوق أسباب تكون مقتضيات لمسبباتها وليس في النار سبب للإحراق ، ولا في الماء قوة الإغراق ولا التبريد ، وهكذا الأمر عندهم سواء ، لا فرق بين الخلق والأمر ، لا فرق في نفس الأمر بين المأمور والمحظور ، ولكن المشيئة اقتضت أمره بهذا ونهيه عن هذا من غير أن يقوم بالمأمور به صفة تقتضي حسنه ، ولا بالمنهي عنه صفة تقتضي قبحه .\rذم هذا المذهب [ وهم الجبرية ]:"], [30, "ولهذا الأصل لوازم فاسدة وفروع كثيرة ، وهؤلاء غالبهم لا يجدون حلاوة العبادة ولا لذتها ولا يتنعمون بها ، ولهذا يسمون الصلاة والصيام والزكاة والحج والتوحيد والإخلاص ونحو ذلك تكاليف ، أي كلفوا بها ولو سمى مدعي محبة ملك من الملوك أو غيره ما يأمره به تكليفاً لم يعد محبا له ، وأول من صدرت عنه هذه المقالة \" الجعد بن درهم \" .\r\rأول بدعة ظهرت في الإسلام ومذهب القدرية والمعتزلة"], [31, "الصنف الثاني : القدرية . النفاة الذين يثبتون نوعاً من الحكمة والتعليل لا يقوم بالرب ولا يرجع إليه .. بل يرجع لمحض مصلحة المخلوق ومنفعته ، فعندهم أن العبادات شرعت أثمانا لما يناله العباد من الثواب والنعيم ، وأنها بمنزلة استيفاء الأجير أجره ، قالوا ، ولهذا يجعلها سبحانه وتعالى عِوضاً كقوله} وَنُودُوا أَنْ تِلْكُمُ الْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ{\"لأعراف: من الآية43\" }هَلْ تُجْزَوْنَ إِلَّا مَا كُنْتُمْ تَعْمَلُونَ{\"النمل: من الآية90\" } ادْخُلُوا الْجَنَّةَ بِمَا كُنْتُمْ تَعْمَلُونَ{\"النحل: من الآية32\" } إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ{\"الزمر: من الآية10\" وفي الصحيح (( إنما هي أعمالكم أحصيها عليك ثم أوفيكم إياها )) قالوا : وقد سماها جزاءً وأجراً وثواباً لأنه شيء يثوب إلى العامل من عمله ، أي يرجع إليه . قالوا : ويدل عليه الموازنة ، فلولا تعلق الثواب بالأعمال عوضاً عليها لم يكن للموازنة معنى ، وهاتان الطائفتان متقابلتان .. فالجبرية لم تجعل للأعمال ارتباطا بالجزاء البتة ، وجوزت أن يعذب الله من أفنى عمره في الطاعة وينعم من أفنى عمره في مخالفته ، وكلاهما سواء بالنسبة إليه ، والكل راجع إلى محض المشيئة ."], [32, "والقدرية أوجبت عليه سبحانه وتعالى رعاية المصالح وجعلت ذلك كله بمحض الأعمال وأن وصول الثواب إلى تفضله سبحانه وتعالى على عبده بمنزلة صدقة العبد على العبد وإعطائه ما يعطيه أجرة على عمله أحب إلى العبد من أن يعطيه فضلاً منه بلا عمل ، ولم يجعلوا للأعمال تأثيراً في الجزاء ألبته ، والطائفتان منحرفتان عن الصراط المستقيم وهو أن الأعمال أسباب موصلة إلى الثواب والأعمال الصالحات من توفيق الله وفضله ، وليست قدراً لجزائه وثوابه بل غايتها إذا وقعت على أكمل الوجوه أن تكون شكراً على أحد الأجزاء القليلة من نعمه سبحانه وتعالى ، فلو عذب أهل سماواته وأهل أرضه لعذبهم وهو غير ظالم لهم ، ولو رحمهم لكانت رحمته خيراً من أعمالهم . وتأمل قوله تعالى }وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ{ \"الزخرف:72\" مع قوله - صلى الله عليه وسلم - (( لن يدخل أحد منكم الجنة بعمله )) تجد الآية تدل على أن الجنان بالأعمال ، والحديث ينفي دخول الجنة بالأعمال ، ولا تنافي بينهما ، لأن توارد النفي والإثبات ليس على محل واحد فالمنفيُّ باء الثمنية واستحقاق الجنة بمجرد الأعمال رداً على القدرية المجوسية التي زعمت أن التفضل بالثواب ابتداءً متضمن لتكدير المنة .\rوالباء المثبتة التي وردت في القرآن هي باء السببية رداً على القدرية الجبرية الذين يقولون لا ارتباط بين الأعمال وجزائها ، ولا هي أسباب لها وإنما غايتها أن تكون إمارة .\rوالسنة النوبية هي أن عموم مشيئة الله وقدرته لا تنافي ربط الأسباب بالمسببات وارتباطها بها ، وكل طائفة من أهل الباطل تركت نوعاً من الحق فإنها ارتكبت لأجله نوعاً من الباطل ، بل أنواعاً ، فهدى الله أهل السنة لما اختلفوا فيه من الحق بإذنه .\r\rأرباب رياضة النفوس وطرائقهم :"], [33, "الصنف الثالث : الذين زعموا أن فائدة العبادة رياضة النفوس واستعدادها لفيض العلوم والمعارف عليها وخروج قواها من قوى النفس السبعية والبهيمية ، فلوا عطلت العبادة لالتحقت بنفوس السباع والبهائم فالعبادة تخرجها إلى مشابهة العقول فتصير قابلة لانتقاش صور المعارف فيها . وهذا يقوله طائفتان أحداهما من الفلاسفة القائلين بقدم العالم وعدم الفاعل المختار . والطائفة الثانية من تفلسف من صوفية الإسلام ويقرب إلى الفلاسفة ، فإنهم يزعمون أن العبادات رياضات لاستعداد النفوس للمعارف العقلية ومخالفة العوائد . ثم من هؤلاء من لا يوجب العبادة إلا بهذا المعنى ، فإذا حصل لها ذلك بقي متحيراً في حفظ أوراده والاشتغال بالوارد عنها ، ومنهم من يوجب القيام بالأوراد وعدم الإخلال بها ، وهم صنفان أيضا : أحدهما من يقول بوجوبها حفظاً للقانون وضبطاً للناموس ، والآخرون يوجبونها حفظاً للوارد وخوفاً من تدرج النفس بمفارقتها إلى حالها الأولى من البهيمية ، فهذه نهاية إقدامهم في حكمة العبادة وما شرعت من لأجله ، ولا تكاد تجد في كتب المتكلمين على طريق السلوك غير طريق من هذه الطرق الثلاثة الأولى .\r\rالطريق الصحيح عقيدة وعملاً :"], [34, "والصنف الرابع : هم القائلون بالجمع بين الخلق والأمر والقدر والسبب فعندهم أن سر العبادة وغايتها مبنيٌّ على معرفة حقيقة الإلهية ومعنى كونه سبحانه وتعالى إلهاً وأن العبادة موجب الإلهية وأثرها ومقتضاها وارتباطها كارتباط متعلق الصفات بالصفات ، وكارتباط المعلوم بالعلم والمقدور بالقدرة ، والأصوات بالسمع والإحسان بالرحمة والإعطاء بالجود ، فعندهم من قام بمعرفتها على النحو الذي فسرناها به لغة وشرعا ومصدراً ومورداً استقام له معرفة حكمة العبادات وغايتها ، وعَلَمَ أنها هي الغاية التي خلقت لها العباد ، ولها أرسلت الرسل ، وأنزلت الكتب ، وخلقت الجنة والنار . وقد صرح سبحانه وتعالى بذلك في قوله}وَمَا خَلَقْتُ الْجِنَّ وَالْأِنْسَ إِلَّا لِيَعْبُدُونِ{ \"الذريات:56\" ، فالعبادة هي التي ما وجدت الخلائق كلها إلا لأجلها ، كما قال تعالى }أَيَحْسَبُ الْأِنْسَانُ أَنْ يُتْرَكَ سُدىً{ \"القيامة:36)\" أي مهملاً . قال الشافعي رحمه الله ، لا يؤمر ولا ينهى ، وقال غيره لا يثاب ولا يعاقب ، وهما تفسيران صحيحان ، فإن الثواب والعقاب مترتب على الأمر والنهي ، والأمر والنهي هو طلب العبادة وإردتها . وحقيقة العبادة امتثالها ."], [35, "ولهذا قال تعالى} وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّار{\"آل عمران: من الآية191” وقال تعالى }وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ {\"الحجر: من الآية85\" }وَخَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ وَلِتُجْزَى كُلُّ نَفْسٍ بِمَا كَسَبَتْ{\"الجاثية: من الآية22\" فأخبر الله تعالى أنه خلق السماوات والأرض بالحق المتضمن أمره ونهيه وثوابه وعقابه ، فإذا كانت السماوات والأرض إنما خلقت لهذا وهو غاية الخلق فكيف يقال إنه لا غاية له ولا حكمة مقصودة ، أو إن ذلك لمجرد استئجار العمال حتى لا يتكدر عليهم الثواب بالمنة ، أو لمجرد استعداد النفوس للمعارف العقلية وارتياضها لمخالفة العوائد .\r\rخلقنا لعبادة الله :"], [36, "وإذا تأملت اللبيب الفرق بين هذه الأقوال وبين ما دل عليه صريح الوحي علم أن الله تعالى إنما خلق الخلقَ لعبادته الجامعة لكمال محبته مع الخضوع له والإنقياد لأمره ، فأصل العبادة محبة الله ، بل إفراده تعالى بالمحبة ، فلا يحب معه سواه ، وإنما يحب ما يحبه لأجله وفيه ، كما يحب أنبياؤه ورسله وملائكته لأن محبتهم من تمام محبته ، وليست كمحبة من اتخذ من دونه أندادا يحبهم كحبه وإذا كانت المحبة له هي حقيقة عبوديته وسرها ، فهي إنما تتحقق باتباع أمره واجتناب نهيه ، فعند اتباع الأمر والنهي تتبين حقيقة العبودية والمحبة ، ولهذا جعل سبحانه وتعالى اتباع رسوله - صلى الله عليه وسلم - علماً عليها وشاهداً لها كما قال تعالى}قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ {\"آل عمران: من الآية31\" ، فجعل اتباع رسوله مشروطاً بمحبتهم الله تعالى وشرطاً لمحبة الله لهم ، وجود المشروط بدون تحقق شرطه ممتنع فَعُلم انتفاء المحبة عند انتفاء المتابعة للرسول . ولا يكفي ذلك حتى يكون الله ورسوله أحب إليها مما سواهما . ومتى كان عنده شيء أحب إليه منهما فهو الإشراك الذي لا يغفره الله . قال تعالى } قُلْ إِنْ كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ وَإِخْوَانُكُمْ وَأَزْوَاجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَالٌ اقْتَرَفْتُمُوهَا وَتِجَارَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَاكِنُ تَرْضَوْنَهَا أَحَبَّ إِلَيْكُمْ مِنَ اللَّهِ وَرَسُولِهِ وَجِهَادٍ فِي سَبِيلِهِ فَتَرَبَّصُوا حَتَّى يَأْتِيَ اللَّهُ بِأَمْرِهِ وَاللَّهُ لا يَهْدِي الْقَوْمَ الْفَاسِقِينَ{ \"التوبة:24\" , وكلُّ مَن قدّم قولَ غير الله على قول الله , أو حكم به , أو حاكم إليه , فليس ممن أحبَّه ."], [37, "لكن قد يشتبه الأمر على مَن يقدّم قولَ أحد أو حكمه أو طاعته على قوله ظناً منه أنه لا يأمر ولا يحكم ولا يقول إلا ما قال الرسول صلى الله عليه وسلم , فيطيعه , ويحاكم إليه , ويتلقى أقواله كذلك , فهذا معذورّ إذا لَم يقدر على غير ذلك\rوأما إذا قدِرَ على الوصول إلى الرسول صلى الله عليه وسلم , وعرف أن غير مَن اتبعه أولى به مطلقاً أو في بعض الأمور كمسألة معينة , ولَم يلتفت إلى قول الرسول صلى الله عليه وسلم , ولا إلى مَن هو أولى به , فهذه يُخاف عليه , وكل ما يتعلل به من عدم العلم , أو عدم الفهم , أو عدم إعطاء آلة الفقه في الدين , أو الاحتجاج بالأشباه والنظائر , أو بأن ذلك المتقدم كان أعلم مني بمراده صلى الله عليه وسلم , فهي كلها تعللات لا تفيد .\rهذا مع الإقرار بجواز الخطأ على غير المعصوم , إلا أن ينازع في هذه القاعدة , فتسقط مكالمته , وهذا هو داخل تحت الوعيد , فإن استحل مع ذلك ثلبَ مَن خالفه , وقرض عرضه ودينه بلسانه , وانتقل من هذا إلى عقوبته , أو السعي في أذاه , فهو من الظلمة المعتدين ونواب المفسدين .\r\rواعلم أنَّ العبادة أربع قواعد , وهي :\r\rالتحقيق بما يحب الله ورسوله ويرضاه , وقيام ذلك بالقلب واللسان والجوارح , فالعبودية اسم جامع لهذه المراتب الأربع , فأصحاب العبادة حقَّا هم أصحابهم .\r\rفقول القلب : هو اعتقاد ما أخبرنا الله تعالى عن نفسه , وأخبر رسوله عن ربه من أسمائه وصفاته وأفعاله وملائكته ولقائه وما أشبه ذلك .\r\rوقول اللسان : الإخبار عنه بذلك , والدعاء إليه , والذب عنه , وتبيين بطلان البدع المخالفة له , والقيام بذكره تعالى , وتبليغ أمره ."], [38, "وعمل القلب : كالمحبة له , والتوكل عليه , والإنابة , والخوف , والرجاء , والإخلاص , والصبر على أوامره ونواهيه , وإقراره , والرضاء به وله وعنه , والموالاة فيه , والمعاداة فيه , والإخبات إليه , والطمأنينة , ونحو ذلك من أعمال القلوب التي فرضُها آكد من فرض أعمال الجوارح , ومستحبُها إلى الله تعالى أحبُّ من مستحب أعمال الجوارح .\rوأما أعمال الجوارح : فكالصلاة , والجهاد , ونقل الأقدام إلى الجمعة والجماعات , ومساعدة العاجز , والإحسان إلى الخلق , ونحو ذلك , فقول العبد في صلواته : { إياك نعبد} التزام أحكام هذه الأربعة وإقرار بها .\rوقوله : { إياك نستعين} طلب الإعانة عليها والتوفيق لها , وقوله : { اهدنا الصراط المستقيم } متضمن للأمرين على التفصيل , وإلهام القيام بهما , وسلوك طريق السالكين إلى الله تعالى .\rوالله الموافق بمنه وكرمه , والحمد لله وحده , وصلى اللهُ على مَن لا نبيَّ بعدَه وآله وصحبه ووارثيه وحزبه .\r\rتَمَّ الكتابُ\rوالحمدُ للهِ أولاً وآخراً"]], "pg": [21, 38]}}, "units": {"1": {"tit": "تجريد التوحيد للمقريزي", "lvl": 1, "pg": [1, 38]}}};
